; EXODUS.BIN: Ultima III (Origin 1983, PC version by James R. Van Artsdalen).
; Generated by tools/gen.py; tools/build.py builds it (MASM, LINK, then the image from 0100).
; HAND: the H command, Hand Equipment, and its menus (7AEA-7D1A).
;
; This is the H command, "Hand Equipment" (Transact itself, the T
; command, is CmdTransact in EQUIP). LOOP's handler (1E55) asks the giver and the receiver and
; calls HandEquip, the menu: Food, Gold, Equipment (gems, keys, powders, torches), Weapons,
; Armour. The amounts are moved by TransferBcd (EQUIP), read by ReadAmount (4 digits) or ReadNumber
; (2). The menus' strings and key lists are in ACTIONS (78B4-795A).
; Also here: AskDirection, the direction prompt every command uses (Look, Bribe, Transact, ...).
CODE SEGMENT BYTE PUBLIC
ASSUME CS:CODE, DS:CODE, ES:CODE, SS:CODE
EXTRN ReadKey:NEAR
EXTRN AskChoice:NEAR
EXTRN ReadNumber:NEAR
EXTRN Sound:NEAR
EXTRN ExoticWeaponFound:BYTE
EXTRN ExoticArmourFound:BYTE
EXTRN ExtraWeaponsOk:BYTE
EXTRN ExtraArmoursOk:BYTE
EXTRN PlayerXY:BYTE
EXTRN MsgMoveNorth:BYTE
EXTRN MsgMoveSouth:BYTE
EXTRN MsgMoveEast:BYTE
EXTRN MsgMoveWest:BYTE
EXTRN PrintMsg:NEAR
EXTRN ScrollMsg:NEAR
EXTRN StatusLine:NEAR
EXTRN MsgHandMenu:BYTE
EXTRN MsgHandEquipMenu:BYTE
EXTRN MsgHowMuch:BYTE
EXTRN MsgNotEnough:BYTE
EXTRN MsgDone:BYTE
EXTRN MsgHowMany:BYTE
EXTRN MsgInUse:BYTE
EXTRN HandMenuKeys:BYTE
EXTRN HandMenuStrs:BYTE
EXTRN HandEquipKeys:BYTE
EXTRN HandEquipStrs:BYTE
EXTRN WeaponMenuKeys:BYTE
EXTRN WeaponMenuStrs:BYTE
EXTRN ArmourMenuKeys:BYTE
EXTRN ArmourMenuStrs:BYTE
EXTRN HandCmdKeys:BYTE
EXTRN HandCmds:BYTE
EXTRN MsgNoMoreRoom:BYTE
EXTRN ReadAmount:NEAR
EXTRN TransferBcd:NEAR
EXTRN MsgWhat:NEAR
PUBLIC AskDirection
PUBLIC HandEquip
PUBLIC HandQuit
PUBLIC HandGold
PUBLIC HandFood
PUBLIC HandItems
PUBLIC HandWeapons
PUBLIC HandArmour
;------------------------------------------------------------------------------
; AskDirection: read an arrow key (others beep) and print North/South/East/West.
; Out: DX = the step (DL x, DH y: -1, 0, +1), BX = PlayerXY + step (wrapped at 64), ZF set
; when Esc was pressed (DX = 0, BX = PlayerXY). Uses: BX, DX.
;------------------------------------------------------------------------------
AskDirection:	push ax	;@7AEA
	push si	;@7AEB
	mov bx, word ptr PlayerXY	;@7AEC
	mov dx, 0	;@7AF0
AskDirection_Key:	call ReadKey	;@7AF3
	cmp ax, 4800h	; Up	;@7AF6
	je AskDirection_North	;@7AF9
	cmp ax, 5000h	; Down	;@7AFB
	je AskDirection_South	;@7AFE
	cmp ax, 4D00h	; Right	;@7B00
	je AskDirection_East	;@7B03
	cmp ax, 4B00h	; Left	;@7B05
	je AskDirection_West	;@7B08
	cmp ax, 11Bh	; Esc	;@7B0A
	je AskDirection_Esc	;@7B0D
	mov al, 0FEh	; error beep	;@7B0F
	call Sound	;@7B11
	jmp AskDirection_Key	;@7B14
AskDirection_North:	lea si, MsgMoveNorth	; "North"	;@7B16
	call PrintMsg	;@7B1A
	mov dh, 0FFh	;@7B1D
	jmp short AskDirection_Done	;@7B1F
AskDirection_South:	lea si, MsgMoveSouth	; "South"	;@7B21
	call PrintMsg	;@7B25
	mov dh, 1	;@7B28
	jmp short AskDirection_Done	;@7B2A
AskDirection_East:	lea si, MsgMoveEast	; "East"	;@7B2C
	call PrintMsg	;@7B30
	mov dl, 1	;@7B33
	jmp short AskDirection_Done	;@7B35
AskDirection_West:	lea si, MsgMoveWest	; "West"	;@7B37
	call PrintMsg	;@7B3B
	mov dl, 0FFh	;@7B3E
AskDirection_Done:	add bl, dl	;@7B40
	add bh, dh	;@7B42
	and bx, 3F3Fh	;@7B44
	test dx, 0FFFFh	; ZF: no step (Esc)	;@7B48
	pop si	;@7B4C
	pop ax	;@7B4D
	ret	;@7B4E
AskDirection_Esc:	call ScrollMsg	;@7B4F
	jmp AskDirection_Done	;@7B52
;------------------------------------------------------------------------------
; HandEquip: the Hand Equipment menu "F, G, E, W, A:" from the player at SI to the
; player at DI. The handlers (table HandCmds) find the two records on the stack frame: [bp+2]
; = SI, the giver; [bp] = DI, the receiver. Ends with "Done!" or an error, then StatusLine.
; In: SI, DI. Note: the pops swap AX and BX on the way out (the caller does not care).
;------------------------------------------------------------------------------
HandEquip:	pushf	;@7B54
	push ax	;@7B55
	push bx	;@7B56
	push cx	;@7B57
	push dx	;@7B58
	push bp	;@7B59
	push si	;@7B5A
	push di	;@7B5B
	cld	;@7B5C
	mov bp, sp	;@7B5D
	lea si, MsgHandMenu	; "F, G, E, W, A:"	;@7B5F
	call PrintMsg	;@7B63
	mov cx, 7	;@7B66
	lea di, HandMenuKeys	; keys F G E W A Q Esc	;@7B69
	lea si, HandMenuStrs	;@7B6D
	call AskChoice	;@7B71
	lea di, HandCmdKeys	; the same keys in the order of the handlers	;@7B74
	mov cx, 7	;@7B78
	mov bx, cx	;@7B7B
	repne scasb	;@7B7D
	sub bx, cx	;@7B7F
	dec bx	;@7B81
	shl bx, 1	;@7B82
	mov si, word ptr [bp+2]	; the giver	;@7B84
	mov di, word ptr [bp]	; the receiver	;@7B87
	jmp word ptr HandCmds[bx]	;@7B8A
HandEquip_Done:	lea si, MsgDone	; "Done!"	;@7B8E
	call PrintMsg	;@7B92
;------------------------------------------------------------------------------
; HandQuit: the end of the Hand menu (also its Q and Esc entries).
;------------------------------------------------------------------------------
HandQuit:	call ScrollMsg	;@7B95
HandEquip_Exit:	call StatusLine	;@7B98
	pop di	;@7B9B
	pop si	;@7B9C
	pop bp	;@7B9D
	pop dx	;@7B9E
	pop cx	;@7B9F
	pop ax	; pushed second: this is BX's value	;@7BA0
	pop bx	;@7BA1
	popf	;@7BA2
	ret	;@7BA3
;------------------------------------------------------------------------------
; HandGold, HandFood: "How much?", 4 digits; move that much gold (record
; 23h) or food (21h, whole units: the hundredths stay) from the giver to the receiver.
;------------------------------------------------------------------------------
HandGold:	mov bx, 23h	; gold	;@7BA4
	jmp short HandGold_Ask	;@7BA7
HandFood:	mov bx, 21h	; food	;@7BA9
HandGold_Ask:	lea si, MsgHowMuch	; "How much? "	;@7BAC
	call PrintMsg	;@7BB0
	call ReadAmount	;@7BB3
	mov si, word ptr [bp+2]	;@7BB6
	mov cx, word ptr [bx+si]	;@7BB9
	mov dx, word ptr [bx+di]	;@7BBB
	call TransferBcd	;@7BBD
	cmp ax, 1	;@7BC0
	je HandEquip_NotEnough	;@7BC3
	cmp ax, 2	;@7BC5
	je HandEquip_NoRoom	;@7BC8
	mov word ptr [bx+si], cx	;@7BCA
	mov word ptr [bx+di], dx	;@7BCC
	jmp HandEquip_Done	;@7BCE
;------------------------------------------------------------------------------
; HandItems: "G, K, P, T:" gems (25h), keys (26h), powders (27h) or torches (0Fh),
; "How much?" (2 digits), at most 99 for the receiver.
;------------------------------------------------------------------------------
HandItems:	lea si, MsgHandEquipMenu	; "G, K, P, T:"	;@7BD0
	call PrintMsg	;@7BD4
	mov cx, 6	;@7BD7
	lea di, HandEquipKeys	;@7BDA
	lea si, HandEquipStrs	;@7BDE
	call AskChoice	;@7BE2
	mov bx, 25h	; gems	;@7BE5
	cmp al, 47h	; 'G'	;@7BE8
	je HandItems_Ask	;@7BEA
	mov bx, 26h	; keys	;@7BEC
	cmp al, 4Bh	; 'K'	;@7BEF
	je HandItems_Ask	;@7BF1
	mov bx, 27h	; powders	;@7BF3
	cmp al, 50h	; 'P'	;@7BF6
	je HandItems_Ask	;@7BF8
	mov bx, 0Fh	; torches	;@7BFA
	cmp al, 54h	; 'T'	;@7BFD
	je HandItems_Ask	;@7BFF
	jmp HandQuit	; Q, Esc	;@7C01
HandEquip_NotEnough:	lea si, MsgNotEnough	; "Not enough!"	;@7C03
	jmp short HandEquip_Fail	;@7C07
HandEquip_NoRoom:	call ScrollMsg	;@7C09
	lea si, MsgNoMoreRoom	; "No more room!"	;@7C0C
	call PrintMsg	;@7C10
	mov al, 0FEh	;@7C13
	call Sound	;@7C15
	jmp HandEquip_Exit	;@7C18
HandEquip_Fail:	call PrintMsg	;@7C1B
	mov al, 0FEh	;@7C1E
	call Sound	;@7C20
	jmp HandQuit	;@7C23
HandItems_Ask:	lea si, MsgHowMuch	; "How much? "	;@7C26
	call PrintMsg	;@7C2A
	call ReadNumber	;@7C2D
	cmp ah, 0FFh	; no number	;@7C30
	je HandEquip_BadNum	;@7C33
	mov ah, 0	;@7C35
	mov si, word ptr [bp+2]	;@7C37
	mov di, word ptr [bp]	;@7C3A
	mov ch, 0	;@7C3D
	mov cl, byte ptr [bx+si]	;@7C3F
	mov dh, 0	;@7C41
	mov dl, byte ptr [bx+di]	;@7C43
	call TransferBcd	;@7C45
	cmp ax, 1	;@7C48
	je HandEquip_NotEnough	;@7C4B
	cmp dh, 0	; more than 99	;@7C4D
	jne HandEquip_NoRoom	;@7C50
	mov byte ptr [bx+si], cl	;@7C52
	mov byte ptr [bx+di], dl	;@7C54
	jmp HandEquip_Done	;@7C56
HandEquip_BadNum:	mov al, 0FEh	;@7C59
	call Sound	;@7C5B
	jmp HandQuit	;@7C5E
;------------------------------------------------------------------------------
; HandWeapons, HandArmour: pick a weapon or armour from the menu (as many
; entries as the flags 14C8-14CB allow), "How many?" (2 digits) and move them. Hand and Skin
; ('A') cannot be given ("<-What?"); the giver's readied weapon or worn armour: "In use!".
;------------------------------------------------------------------------------
HandWeapons:	mov bx, 30h	; weapons (30h + index)	;@7C61
	mov cx, 12h	; 18 entries: up to Exotic	;@7C64
	cmp byte ptr ExoticWeaponFound, 0FFh	;@7C67
	je HandWeapons_Menu	;@7C6C
	mov cx, 11h	; 17: up to +4 Swd	;@7C6E
	cmp byte ptr ExtraWeaponsOk, 0FFh	;@7C71
	je HandWeapons_Menu	;@7C76
	mov cx, 0Ah	; 10: up to 2-H-Swd	;@7C78
HandWeapons_Menu:	lea di, WeaponMenuKeys	;@7C7B
	lea si, WeaponMenuStrs	;@7C7F
	jmp short HandArms_Pick	;@7C83
HandArmour:	mov bx, 28h	; armours (28h + index)	;@7C85
	mov cx, 0Ah	; 10: up to Exotic	;@7C88
	cmp byte ptr ExoticArmourFound, 0FFh	;@7C8B
	je HandArmour_Menu	;@7C90
	mov cx, 9	; 9: up to +2 Plate	;@7C92
	cmp byte ptr ExtraArmoursOk, 0FFh	;@7C95
	je HandArmour_Menu	;@7C9A
	mov cx, 7	; 7: up to Plate	;@7C9C
HandArmour_Menu:	lea di, ArmourMenuKeys	;@7C9F
	lea si, ArmourMenuStrs	;@7CA3
HandArms_Pick:	call ScrollMsg	;@7CA7
	call AskChoice	;@7CAA
	cmp al, 41h	; 'A': Hand or Skin	;@7CAD
	je HandArms_What	;@7CAF
	cmp al, 51h	; 'Q'	;@7CB1
	je HandArms_Quit	;@7CB3
	cmp al, 1Bh	; Esc	;@7CB5
	je HandArms_Quit	;@7CB7
	mov dl, al	;@7CB9
	lea si, MsgHowMany	; "How many? "	;@7CBB
	call PrintMsg	;@7CBF
	mov si, word ptr [bp+2]	;@7CC2
	mov di, word ptr [bp]	;@7CC5
	call ReadNumber	;@7CC8
	cmp ah, 0FFh	;@7CCB
	je HandEquip_BadNum	;@7CCE
	cmp al, 0	;@7CD0
	je HandArms_Quit	;@7CD2
	sub dl, 41h	; the index	;@7CD4
	mov ah, byte ptr [bx+si]	; the giver's weapon readied / armour worn	;@7CD7
	mov dh, 0	;@7CD9
	add bx, dx	;@7CDB
	cmp ah, dl	;@7CDD
	je HandArms_InUse	;@7CDF
	mov ah, 0	;@7CE1
	mov cl, byte ptr [bx+si]	; the counts owned	;@7CE3
	mov ch, 0	;@7CE5
	mov dl, byte ptr [bx+di]	;@7CE7
	mov dh, 0	;@7CE9
	call TransferBcd	;@7CEB
	cmp ax, 1	;@7CEE
	je HandArms_NotEnough	;@7CF1
	cmp dh, 0	; more than 99	;@7CF3
	jne HandArms_NoRoom	;@7CF6
	mov byte ptr [bx+si], cl	;@7CF8
	mov byte ptr [bx+di], dl	;@7CFA
	jmp HandEquip_Done	;@7CFC
HandArms_Quit:	jmp HandQuit	;@7CFF
HandArms_What:	jmp MsgWhat	; to MainLoop with 18 bytes left on the stack (bug)	;@7D02
HandArms_NotEnough:	jmp HandEquip_NotEnough	;@7D05
HandArms_NoRoom:	jmp HandEquip_NoRoom	;@7D08
HandArms_InUse:	mov al, 0FEh	;@7D0B
	call Sound	;@7D0D
	lea si, MsgInUse	; "In use!"	;@7D10
	call PrintMsg	;@7D14
	jmp HandQuit	;@7D17
CODE ENDS
END
